import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_normal_vehicle_repair_v1';R=ROOT/'data/exp/estimation/three_ward_normal_vehicle_repair_v1';OLD=ROOT/'data/exp/estimation/three_ward_normal_vehicle_baseline_v1'
ARMS=['A_original_single','B_topology_single','C_topology_multi'];NAMES={'A_original_single':'A Original','B_topology_single':'B Native-node repair','C_topology_multi':'C Repair + distributed access'};CN={'A_original_single':'A 原始连接＋单接入','B_topology_single':'B 修复连接＋单接入','C_topology_multi':'C 修复连接＋多接入'}
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):
 h=hashlib.sha256()
 with p.open('rb')as f:
  for block in iter(lambda:f.read(8*1024*1024),b''):h.update(block)
 return h.hexdigest()
def main():
 s=json.loads((R/'summary.json').read_text());v=json.loads((R/'validation.json').read_text());assert v['passed'];prep=s['preparation'];m=pd.read_csv(P/'flow_metrics.csv');d=pd.read_csv(P/'passage_comparison.csv');sel=m.branch.eq('base_no_remote_remote')&m.period.eq('daytime12h')&m.comparison_class.eq('small');dev='development_previously_inspected20';cal='development_original_calibration65'
 def val(arm,role=dev,cls='all',branch='base_no_remote_remote'):
  return m[(m.arm.eq(arm)&m.evaluation_role.eq(role)&m.road_class.eq(cls)&m.branch.eq(branch)&m.period.eq('daytime12h')&m.comparison_class.eq('small'))].iloc[0]
 x=d[d.branch.eq('base_no_remote_remote')&d.period.eq('daytime12h')&d.comparison_class.eq('small')&d.evaluation_role.eq(dev)];plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f5f8fa'});fig,axes=plt.subplots(1,3,figsize=(13,4.9));limit=np.ceil(max(x.observed.max(),x.predicted.max())/10000)*10000
 for ax,arm in zip(axes,ARMS):
  g=x[x.arm.eq(arm)]
  for cls,col,marker,label in [('ordinary','#227c9b','o','Ordinary (n=14)'),('expressway','#b57936','s','Expressway (n=6)')]:
   t=g[g.road_class.eq(cls)];ax.scatter(t.observed/1000,t.predicted/1000,color=col,marker=marker,s=36,edgecolor='white',linewidth=.4,label=label)
  ax.plot([0,limit/1000],[0,limit/1000],ls='--',color='#9baab1',lw=1);ax.set(xlim=(-1,limit/1000),ylim=(-1,limit/1000),title=NAMES[arm],xlabel='Observed small vehicles (thousand / 12 h)');ax.grid(alpha=.15)
 axes[0].set_ylabel('Modeled driver proxy (thousand / 12 h)');axes[0].legend(fontsize=7,frameon=False);fig.suptitle('Previously inspected 20 screenlines: development comparison, not an independent test',fontsize=12);fig.tight_layout(rect=[0,.18,1,.93]);fig.text(.5,.035,'Same 2018 driver-candidate OD, time shares, physical road arcs, permissions, turn rules and 2021 count targets.\nBase branch; both directions, 07:00–19:00. A→B changes source-supported grade connectors; B→C changes local zone access only.\nDistance-only assignment; no predicted travel speeds, congestion or affected people. No demand multiplier fitted.',ha='center',fontsize=8);fig.savefig(R/'flow_repair_comparison.png',dpi=170);plt.close(fig)
 fig,(ax,bx)=plt.subplots(1,2,figsize=(11,4.6));cols=['#9cabb4','#c58f50','#317d9c'];xx=np.arange(3)
 for offset,role,label in [(-.18,cal,'Original calibration 65 (development)'),(.18,dev,'Previously inspected 20 (development)')]:
  vals=[val(a,role).wape*100 for a in ARMS];bars=ax.bar(xx+offset,vals,.34,label=label,color=cols,alpha=1 if offset<0 else .55)
  for bar,z in zip(bars,vals):ax.text(bar.get_x()+bar.get_width()/2,z+2,f'{z:.0f}%',ha='center',fontsize=8)
 ax.set_xticks(xx,['A','B','C']);ax.set(ylabel='WAPE (%) — lower is better',title='Raw 12 h small-vehicle count error');ax.set_ylim(0,max([val(a,r).wape*100 for a in ARMS for r in [cal,dev]])*1.38);ax.legend(fontsize=8,frameon=False,loc='upper right');ax.grid(axis='y',alpha=.15)
 for i,arm in enumerate(ARMS):
  ordinary=round(val(arm,dev,'ordinary').zero_prediction_fraction*14);express=round(val(arm,dev,'expressway').zero_prediction_fraction*6);bx.bar(i,ordinary,color='#227c9b',label='Ordinary'if i==0 else None);bx.bar(i,express,bottom=ordinary,color='#b57936',label='Expressway'if i==0 else None);bx.text(i,ordinary+express+.2,str(ordinary+express),ha='center')
 bx.set_xticks(xx,['A','B','C']);bx.set(ylabel='Zero-assignment screenlines (out of 20)',ylim=(0,11),title='Previously inspected group');bx.legend(fontsize=8,frameon=False);bx.grid(axis='y',alpha=.15);fig.tight_layout(rect=[0,.14,1,1]);fig.text(.5,.025,'WAPE = sum absolute error / sum observed count. It is not accuracy. Bars compare model development variants.\nThe original source-group split is unchanged; neither group is a fresh validation sample after inspection.',ha='center',fontsize=8);fig.savefig(R/'flow_metrics.png',dpi=170);plt.close(fig)
 def link(n,label):return f'<a href="{html.escape(os.path.relpath(P/n,R))}">{label}</a>'
 rows=''
 for a in ARMS:
  for role,label in [(cal,'原65断面（开发）'),(dev,'原20断面（开发）')]:
   q=val(a,role);rows+=f'<tr><td>{CN[a]}</td><td>{label}</td><td>{q.prediction_observation_ratio:.1%}</td><td>{q.wape:.1%}</td><td>{q.zero_prediction_fraction:.1%}</td></tr>'
 clsrows=''
 for a in ARMS:
  for cls,label in [('ordinary','普通道路14个'),('expressway','高速道路6个')]:
   q=val(a,dev,cls);clsrows+=f'<tr><td>{CN[a]}</td><td>{label}</td><td>{q.prediction_observation_ratio:.1%}</td><td>{q.wape:.1%}</td><td>{round(q.zero_prediction_fraction*q.n)} / {int(q.n)}</td></tr>'
 throughrows=''
 for a in ARMS:
  q=val(a,dev,branch='plus_conditional_chord_through');throughrows+=f'<tr><td>{CN[a]}</td><td>{q.prediction_observation_ratio:.1%}</td><td>{q.wape:.1%}</td><td>{q.zero_prediction_fraction:.0%}</td></tr>'
 before=prep['motorway_arcs_main_scc_before']/prep['motorway_arcs'];after=prep['motorway_arcs_main_scc_after']/prep['motorway_arcs'];aa,bb,cc=[val(a)for a in ARMS]
 doc=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>常态交通修正：高速连接与分区多接入对照</title><style>body{{font:16px/1.75 system-ui,sans-serif;color:#243b49;background:#f2f6f8;margin:0}}main{{max-width:1120px;margin:auto;padding:35px 25px;overflow-wrap:anywhere}}h1{{font-size:31px;line-height:1.35}}h2{{font-size:23px;margin-top:34px}}.lead{{font-size:19px}}.box{{background:white;border:1px solid #dae5eb;border-radius:12px;padding:20px;margin:20px 0}}.warn{{border-left:5px solid #bd8640}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.metric{{padding:17px;background:white;border-radius:10px}}.big{{font-size:28px;font-weight:700;display:block}}.muted{{font-size:14px;color:#607784}}img{{max-width:100%;height:auto}}a{{color:#146b93}}.table{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;background:white}}th,td{{padding:10px;border-bottom:1px solid #dbe5eb;text-align:left;vertical-align:top}}li{{margin:9px 0}}@media(max-width:650px){{main{{padding:23px 14px}}h1{{font-size:26px}}.metrics{{grid-template-columns:repeat(2,1fr)}}table{{min-width:580px;font-size:13px}}.metric .rate{{font-size:20px;white-space:nowrap}}}}</style><main><p class="muted">千代田区 · 中央区 · 港区及10km道路范围 ｜ 2026-10-18 ｜ 正常交通分配开发诊断</p><h1>高速连接已批量修正；<br>用固定OD分开检验连接和接入效果。</h1><p class="lead">本次保留原车辆候选需求、时段比例、道路权限、转向限制和全部85个实测比较断面。A复用原结果，B只修复源拓扑支持的高速连接，C在B基础上分散分区接入。连接覆盖改善不能直接等同为车流拟合或拥堵预测已经合格。</p>
<div class="metrics"><div class="metric"><span class="big">421</span>新增同原生节点连接对</div><div class="metric"><span class="big rate">10.3%→89.7%</span>高速弧主双向连通支持</div><div class="metric"><span class="big">145→528</span>单接入 / 多接入节点</div><div class="metric"><span class="big">85</span>固定观测断面</div></div>
<div class="box warn"><b>验证角色已明确调整。</b><p>此前20个留出断面的表现已经被查看并用于发现问题。本轮仍保留原65＋20编号分组，但两组均作为开发诊断，不再声称20个是独立验证集。尚未配置新的封存交通验证样本；已有水动力/机器学习封存测试没有打开。</p></div>
<h2>修正的系统性问题</h2><p>原图把相对 <code>layer</code> 不同的桥上道路视为不同层而断开。批量检查找到496条涉及高速/匝道的原生节点冲突记录：其中479条满足连接证据，去重为421对；17条因不能同时确认两条源道路都在原允许图中而暂留。典型情形是高速在同一个源节点连续延伸，<code>layer=3</code>变为<code>layer=4</code>；这个相对上下关系变化本身不能证明车辆不能沿路通过。<a href="https://wiki.openstreetmap.org/wiki/Key:layer">OSM的layer说明</a>将其限定为局部交叉或重叠对象的垂直关系，并明确层号变化不表示高程变化；本项目的连接判断另由原生拓扑和权限证据约束。</p><p>修正版只处理<b>相同原生OSM节点、至少一条为高速/匝道、至少一条源道路端点、两条源道路均已允许车行、节点权限允许、无相互矛盾的显式楼层</b>的连接。不按坐标相交或距离吸附。桥隧绝对路面高程仍然未知，未赋成地面DEM高程；原版A保留为保守分支。</p><p>高速及匝道共2,071条有向弧，两端均在主强连通部分的数量由213增至1,858。源机动车物理道路弧没有新增或删除，新增的是842条有向零长度原生节点连接。相同连通分量下重建的转向路由与原核心CSR逐项一致，修正后继续使用原1,286条已支持规则；138条条件限制及37个原暂留源way的处理没有放松。</p>
<h2>分离对照如何保持可比</h2><div class="table"><table><tr><th>组</th><th>道路连接</th><th>分区接入</th><th>需求与选路</th></tr><tr><td>A</td><td>原保守源图</td><td>原145节点</td><td rowspan="3">相同源OD、5个时段、2种远端穿越分支；仍为最短距离全有或全无分配，不拟合需求倍数</td></tr><tr><td>B</td><td>修复421对原生节点</td><td>原145节点保持不变</td></tr><tr><td>C</td><td>与B相同</td><td>原129个本地分区各最多4个地面接入；外围16个门户不变，共528节点</td></tr></table></div><p>C从原本允许车行的原生地面节点中选取空间分散点，至少相隔150m；原接入点保留，新增接入点等权。每个原细分OD按两端接入点的等权乘积分配，分数最大守恒残差约1.1×10⁻¹⁶。它是空间覆盖假设，尚无住址/停车出入口级OD证据。原同分区暂留行程仍暂留，本轮没有借此增加需求池或重新安排远端门户。</p>
<h2>车流是否改善：先看原始结果</h2><img src="flow_repair_comparison.png" alt="A原始、B连接修复、C多接入在原20断面的预测和实测车流对照"><div class="table"><table><tr><th>组</th><th>比较组</th><th>预测/实测总量比</th><th>WAPE</th><th>零分配断面比例</th></tr>{rows}</table></div><p class="muted">7–19时、双向、小型车，基础远端需求分支。总量比是相同断面通行次数之和之比，不是独立车辆或需求覆盖率。WAPE=Σ|预测−实测|/Σ实测，不是准确率。三个单小时、真正完整24小时和全部车型结果另存CSV。</p><img src="flow_metrics.png" alt="三组在两个开发分组的误差和原20断面零分配数量"><div class="box"><b>分开解释两步改变：</b><p>在原20断面的开发对照中，A→B总量比由{aa.prediction_observation_ratio:.1%}变为{bb.prediction_observation_ratio:.1%}，WAPE由{aa.wape:.1%}变为{bb.wape:.1%}；B→C总量比变为{cc.prediction_observation_ratio:.1%}，WAPE变为{cc.wape:.1%}。这里反映的是固定需求下连接与接入假设的影响，不能据此断言真实交通已还原，也未按这20个断面反复调参或选模。</p></div>
<h2>普通道路与高速道路</h2><div class="table"><table><tr><th>组</th><th>原20断面中的类别</th><th>预测/实测总量比</th><th>WAPE</th><th>零分配断面</th></tr>{clsrows}</table></div><p>应同时看两个类别，避免把高速流量恢复误认为所有道路都改善。仍然低估、过高或零分配的位置保持为模型残差，不解释为实际无车或道路关闭。本轮只作三区整体与道路类别汇总，没有逐点调查。</p><h2>远端穿越假设是否改变判断</h2><div class="table"><table><tr><th>组（加入条件性穿越）</th><th>原20断面总量比</th><th>WAPE</th><th>零分配比例</th></tr>{throughrows}</table></div><p>两种穿越分支及其源量均沿用原版，不因当前结果修改。远端分区代表点连线穿过范围仍然只是穿越需求假设；修复后的高速连接支持增加，不代表远端实际入口或收费道路选择已经观测确认。</p>
<h2>本阶段能做什么、下一步是什么</h2><p>已完成系统性原生连接修正和多接入分离对照；数值流量守恒和源OD不变检查通过。仍然没有车速、通行能力、排队或拥堵响应，不能由当前最短距离分配直接发布可信延误或措施收益。2018驾驶候选、2021道路观测和2026路网的年份及车辆覆盖差异仍然存在。</p><p><b>接下来应固定这次结构修正，建立简化的常态行驶时间分配。</b>利用已有旅行速度、限速和道路等级设置明确的速度假设；先比较距离选路与时间选路，再确定必要的容量情景。分区多接入目前作为敏感性分支，不因开发组结果较好就自动确认为真实OD。独立验证需要新的观测单元或事件设计，不能把已查看的20断面重新封存后称为独立。</p><p>本轮没有新水动力、训练或受影响人数计算；严格道路、步道补缺及洪水暴露未知分支未被合并。修正版另存，原模型和独立水动力批次未改写。</p><h2>本地证据与复现</h2><p>{link('protocol.json','对照协议')} · {link('native_motorway_repair_evidence.csv','连接证据及暂留原因')} · {link('multi_network_endpoints.csv','多接入节点与假设')} · {link('paired_screenline_changes.csv','逐断面对照表')} · {link('passage_comparison.csv','全部时段/车型结果')} · {link('flow_metrics.csv','全部指标')} · <a href="preparation_summary.json">连接和输入核验</a> · <a href="validation.json">结果完整性</a> · <a href="summary.json">汇总</a> · <a href="{os.path.relpath(OLD/'review.html',R)}">上一轮基线</a></p><p>复现：prepare_normal_vehicle_repair_v1.py → run_normal_vehicle_repair_v1.py → evaluate_normal_vehicle_repair_v1.py → report_normal_vehicle_repair_v1.py。源文件SHA-256已绑定，未修改原始资料、AnaSOP、Git或DVC。</p><p><a href="https://www.tokyo-pt.jp/data/H30">東京都市圈PT官方数据</a> · <a href="https://www.mlit.go.jp/road/census/r3/index.html">国土交通省道路普查</a> · <a href="https://www.openstreetmap.org/copyright">© OpenStreetMap contributors / ODbL</a></p><p class="muted">官方统计及OSM源拓扑经本项目加工；修正分支是研究模型解释，不是现场高程、实时交通或法定通行认证。Framelog：MILI-D-20261018-002。</p></main></html>'''
 (R/'review.html').write_text(doc)
 files=[p for p in P.iterdir()if p.is_file()]+[p for p in R.iterdir()if p.is_file()and p.name not in ['delivery_manifest.json','browser_validation.json','review_desktop.png','review_mobile.png']]+[ROOT/'src/preprocessing/prepare_normal_vehicle_repair_v1.py']+[ROOT/'src/analyses'/n for n in ['run_normal_vehicle_repair_v1.py','evaluate_normal_vehicle_repair_v1.py','report_normal_vehicle_repair_v1.py','validate_normal_vehicle_repair_browser_v1.cjs']]
 dump(R/'delivery_manifest.json',{'created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)}for p in files if p.exists()]});print('Repair development report ready.')
if __name__=='__main__':main()
